-- Inserts a template test's benchmarks for one metric row.
create or replace function seed_youth_benchmarks(p_metric_id uuid, p_metric_name text)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  b jsonb;
begin
  for b in select * from jsonb_array_elements(youth_battery_template()->'benchmarks') loop
    if b->>'metric' = p_metric_name then
      insert into test_benchmarks (test_metric_id, benchmark_type, sex, age_min, age_max,
        average_threshold, good_threshold, excellent_threshold, elite_threshold, quality, sources)
      values (p_metric_id, b->>'type', b->>'sex', (b->>'min')::numeric, (b->>'max')::numeric,
        (b->>'avg')::numeric, (b->>'good')::numeric, (b->>'exc')::numeric, (b->>'elite')::numeric,
        b->>'quality', b->>'sources');
    end if;
  end loop;
end;
$$;

-- Adds a template test to an org (if it isn't there by name), with its
-- benchmarks, and links it to the given battery.
create or replace function seed_youth_metric(p_org_id uuid, p_battery_id uuid, p_metric jsonb)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  v_metric_id uuid;
begin
  select id into v_metric_id from test_metrics
   where organisation_id = p_org_id and name = p_metric->>'name' limit 1;
  if v_metric_id is null then
    insert into test_metrics (
      organisation_id, name, unit, better_direction, requires_bodyweight, is_bilateral, screening_only,
      what_it_measures, why_it_matters, notes,
      commentary_elite, commentary_excellent, commentary_good, commentary_average, commentary_needs_work
    ) values (
      p_org_id, p_metric->>'name', p_metric->>'unit', p_metric->>'better_direction',
      (p_metric->>'requires_bodyweight')::boolean, (p_metric->>'is_bilateral')::boolean, (p_metric->>'screening_only')::boolean,
      coalesce(p_metric->>'what_it_measures', ''), coalesce(p_metric->>'why_it_matters', ''), coalesce(p_metric->>'notes', ''),
      coalesce(p_metric->'commentary'->>'elite', ''), coalesce(p_metric->'commentary'->>'excellent', ''),
      coalesce(p_metric->'commentary'->>'good', ''), coalesce(p_metric->'commentary'->>'average', ''),
      coalesce(p_metric->'commentary'->>'needs_work', '')
    ) returning id into v_metric_id;
    perform seed_youth_benchmarks(v_metric_id, p_metric->>'name');
  end if;
  if p_battery_id is not null and not exists (
    select 1 from test_battery_metrics where test_battery_id = p_battery_id and test_metric_id = v_metric_id
  ) then
    insert into test_battery_metrics (test_battery_id, test_metric_id, sort_order)
    values (p_battery_id, v_metric_id,
      coalesce((select max(sort_order) + 1 from test_battery_metrics where test_battery_id = p_battery_id), 0));
  end if;
  return v_metric_id;
end;
$$;

-- Whole youth battery for a new org. Skips an org that already has it.
create or replace function seed_youth_battery(p_org_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  t jsonb := youth_battery_template();
  v_battery_id uuid;
  m jsonb;
begin
  if exists (select 1 from test_batteries where organisation_id = p_org_id and name = t->'battery'->>'name') then
    return;
  end if;
  insert into test_batteries (organisation_id, name, description)
  values (p_org_id, t->'battery'->>'name', t->'battery'->>'description')
  returning id into v_battery_id;
  for m in select * from jsonb_array_elements(t->'metrics') loop
    perform seed_youth_metric(p_org_id, v_battery_id, m);
  end loop;
end;
$$;

create or replace function trg_seed_youth_battery()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  -- Never let a default-battery seed failure block signup.
  begin
    perform seed_youth_battery(new.id);
  exception when others then
    raise warning 'seed_youth_battery failed for org %: %', new.id, sqlerrm;
  end;
  return new;
end;
$$;

drop trigger if exists organisations_seed_youth on organisations;
create trigger organisations_seed_youth
  after insert on organisations
  for each row
  execute function trg_seed_youth_battery();

revoke all on function youth_battery_template() from public, anon, authenticated;
revoke all on function seed_youth_benchmarks(uuid, text) from public, anon, authenticated;
revoke all on function seed_youth_metric(uuid, uuid, jsonb) from public, anon, authenticated;
revoke all on function seed_youth_battery(uuid) from public, anon, authenticated;
revoke all on function trg_seed_youth_battery() from public, anon, authenticated;

-- ------------------------------------------------------------
-- Existing organisations.
-- ------------------------------------------------------------
do $$
declare
  t jsonb := youth_battery_template();
  o record;
  met record;
  m jsonb;
  v_battery_id uuid;
begin
  -- Tests that already exist: new norms + Elite commentary.
  for met in select tm.id, tm.name from test_metrics tm where tm.name in ('10m Sprint', '505 Change of Direction', 'Anterior Hold', 'Countermovement Jump', 'IMTP Relative (N/kg)', 'Reactive Strength Index (10-5)', 'Side Plank', 'Single Leg CMJ') loop
    select x into m from jsonb_array_elements(t->'metrics') x where x->>'name' = met.name;
    update test_metrics set commentary_elite = coalesce(m->'commentary'->>'elite', '') where id = met.id;
    delete from test_benchmarks where test_metric_id = met.id;
    perform seed_youth_benchmarks(met.id, met.name);
  end loop;

  -- Single Leg CMJ: now rated on the better leg (asymmetry screen stays).
  select x into m from jsonb_array_elements(t->'metrics') x where x->>'name' = 'Single Leg CMJ';
  update test_metrics set
    screening_only = false,
    what_it_measures = m->>'what_it_measures',
    notes = m->>'notes',
    commentary_excellent = m->'commentary'->>'excellent',
    commentary_good = m->'commentary'->>'good',
    commentary_average = m->'commentary'->>'average',
    commentary_needs_work = m->'commentary'->>'needs_work'
  where name = 'Single Leg CMJ';

  -- New tests into every org's youth battery (or the whole battery for
  -- an org without one).
  for o in select id from organisations loop
    select id into v_battery_id from test_batteries
     where organisation_id = o.id and name = t->'battery'->>'name' limit 1;
    if v_battery_id is null then
      perform seed_youth_battery(o.id);
      continue;
    end if;
    for m in select * from jsonb_array_elements(t->'metrics') loop
      if m->>'name' in ('Prone Hold', 'Press-up', 'Multi-Stage Fitness Test (Bleep Test)', 'Standing Broad Jump', 'CMJ Peak Force (kg)', 'DSI (CMJ/IMTP)') then
        perform seed_youth_metric(o.id, v_battery_id, m);
      end if;
    end loop;
  end loop;
end $$;
